/* Venn prototype — authentication and onboarding (simulated: no real auth, no email, no network) */
const box = (title, sub, body, wide = false) => `<div class="proto"><b>PROTOTYPE</b><span class="hide-s">Simulated authentication · nothing is sent or stored</span><span class="sp"></span><a href="index.html">Website</a><a href="app.html">Skip to app</a></div><main class="auth"><div class="box ${wide ? 'wide' : ''}"><a class="logo" href="index.html">${LOGO_D}Venn</a><h1>${title}</h1>${sub ? `<p class="muted mt8 mb16">${sub}</p>` : '<div class="mb16"></div>'}${body}</div><p class="small muted mt16">Your data is isolated per organization.</p></main>`;
const A = { email: '', ob: { sources: {}, mail: {}, team: [] } };
const OB = ['Organization', 'Sources', 'Email', 'Import', 'Team', 'Preferences'];
const AUTH = {
  login: () => box('Sign in', 'One login for owners and AR specialists.', form('fl', fld('Email', '<input class="in" data-req data-email name="e" type="email" autocomplete="username">', '', 'Enter a valid email address') + fld('Password', '<input class="in" data-req name="p" type="password" autocomplete="current-password">') + `<button class="btn btn-primary" style="width:100%" data-act="doLogin">Sign in</button>`) + `<p class="small mt16"><a href="#/forgot">Forgot password?</a> · <a href="#/signup">Create an account</a></p><hr style="border:0;border-top:1px solid var(--border);margin:20px 0"><div class="small muted mb16">Prototype shortcuts</div><div class="pill-links"><button class="btn btn-sm" data-act="quick" data-role="owner">Sign in as Owner (Dana)</button><button class="btn btn-sm" data-act="quick" data-role="ar">Sign in as AR Specialist (Priya)</button></div>`),
  signup: () => box('Create your account', 'Start with your work email.', form('fs', fld('Full name', '<input class="in" data-req name="n" autocomplete="name">') + fld('Work email', '<input class="in" data-req data-email name="e" type="email">', '', 'Enter a valid email address') + fld('Password', '<input class="in" data-req data-min="12" name="p" type="password" autocomplete="new-password">', 'At least 12 characters. Passwords found in known breaches are rejected.', 'Use at least 12 characters') + `<label class="check mb16"><input type="checkbox" data-req> <span>I agree to the <a href="index.html#/terms">terms</a> and <a href="index.html#/privacy">privacy policy</a>.</span></label><button class="btn btn-primary" style="width:100%" data-act="doSignup">Create account</button>`) + `<p class="small mt16">Already have an account? <a href="#/login">Sign in</a></p>`),
  verify: () => box('Check your email', `We sent a verification link to <b>${esc(A.email || 'your email')}</b>. Verify it to continue. (If this address is already registered, the email will say so; this page looks the same either way.)`, `<button class="btn btn-primary" data-act="verified">Prototype: simulate clicking the link</button><div class="row mt16"><button class="btn btn-sm" data-act="resend" id="rs">Resend email</button><span class="small muted" id="rsn"></span></div><p class="small mt16"><a href="#/signup">Use a different email</a></p>`),
  forgot: () => box('Reset your password', 'Enter your email and we will send a reset link if an account exists.', form('ff', fld('Email', '<input class="in" data-req data-email name="e" type="email">', '', 'Enter a valid email address') + `<button class="btn btn-primary" data-act="doForgot">Send reset link</button>`) + `<p class="small mt16"><a href="#/login">Back to sign in</a></p>`),
  reset: () => box('Choose a new password', '', form('fr', fld('New password', '<input class="in" data-req data-min="12" name="p" type="password">', 'At least 12 characters.', 'Use at least 12 characters') + fld('Confirm password', '<input class="in" data-req data-min="12" name="c" type="password">') + `<button class="btn btn-primary" data-act="doReset">Update password</button>`)),
  invite: () => box('You\'re invited', 'Brightpath Digital (demo)', `<div class="banner">${ic('info')}<div><b>Dana Whitfield</b> invited you to join <b>Brightpath Digital (demo)</b> as an <b>AR Specialist</b>. You will join the existing organization; a new one is never created.</div></div>${form('fv', fld('Email', '<input class="in" value="tom@brightpath.example" disabled>', 'The invitation is for this address.') + fld('Full name', '<input class="in" data-req name="n" value="Tom Ellery">') + fld('Password', '<input class="in" data-req data-min="12" name="p" type="password" autocomplete="new-password">', 'At least 12 characters.', 'Use at least 12 characters') + `<button class="btn btn-primary" style="width:100%" data-act="acceptInvite">Create account and join</button>`)}<p class="small muted mt16">Already have a Venn account with this email? <a href="#/login">Sign in to accept</a>. Expired link? Ask the Owner to resend.</p>`),
};
function onboarding(n) {
  const steps = `<div class="stepper">${OB.map((s, k) => `${k ? '<span class="sep"></span>' : ''}<span class="st ${n === k + 1 ? 'on' : n > k + 1 ? 'done' : ''}"><span class="n">${n > k + 1 ? '✓' : k + 1}</span><span class="hide-s">${s}</span></span>`).join('')}</div>`;
  const nav = (primary = 'Continue', skip = n > 1) => `<div class="row mt24">${n > 1 ? `<a class="btn" href="#/onboarding/${n - 1}">Back</a>` : ''}<span class="sp"></span>${skip ? `<a class="btn btn-ghost" href="#/onboarding/${n + 1}" data-act="skip">Skip for now</a>` : ''}<button class="btn btn-primary" data-act="obNext" data-n="${n}">${primary}</button></div>`;
  const srcCard = (id, t, d, st) => `<div class="card mb16"><div class="card-b row"><div class="sp"><b>${t}</b><div class="small muted">${d}</div></div>${st === 'ok' ? `<button class="btn btn-sm ${A.ob.sources[id] ? '' : 'btn-primary'}" data-act="obToggle" data-k="${id}">${A.ob.sources[id] ? 'Selected ✓' : 'Select'}</button>` : '<span class="badge b-neutral nodot">Coming soon</span>'}</div></div>`;
  let b = '';
  if (n === 1) b = `<h2 class="mb16">Create your organization</h2>${form('fo', fld('Organization name', '<input class="in" data-req name="n" placeholder="Acme Digital">') + fld('Industry', '<select class="in" data-req name="i"><option value="">Select…</option><option>Software development agency</option><option>IT consulting</option><option>Managed services</option><option>Staffing and recruitment</option><option>Professional services</option><option>Other B2B services</option></select>') + `<div class="grid g2"><div>${fld('Company size', '<select class="in" data-req name="s"><option value="">Select…</option><option>1–10</option><option>11–50</option><option>51–200</option><option>200+</option></select>')}</div><div>${fld('Country', '<select class="in" data-req name="c"><option value="">Select…</option><option>United States</option><option>United Kingdom</option><option>Canada</option><option>Germany</option><option>Other</option></select>')}</div></div>` + fld('Default currency', '<select class="in" name="d"><option>USD</option><option>EUR</option><option>GBP</option><option>CAD</option></select>', 'Preselected from your country; you can change it later.') + fld('Website (optional)', '<input class="in" placeholder="https://">'))}${nav('Create organization', false)}`;
  if (n === 2) b = `<h2 class="mb16">Connect financial sources</h2><p class="muted mb16">Optional. You can start with CSV files and connect more later.</p>${srcCard('csv', 'Upload CSV files', 'Invoices and bank or gateway payments', 'ok')}${srcCard('qb', 'QuickBooks Online', 'Read-only sync of customers, invoices, payments', 'ok')}${srcCard('stripe', 'Stripe', 'Read-only charges, payouts and refunds', 'ok')}${srcCard('xero', 'Xero', 'Planned after the first release', 'soon')}${nav()}`;
  if (n === 3) b = `<h2 class="mb16">Connect email</h2><p class="muted mb16">Optional. Venn reads only messages matching a financial filter, with the minimum permissions below.</p><div class="card mb16"><div class="card-b"><b>Gmail</b><ul class="small muted"><li>Read messages from your customers' contacts or mentioning invoice numbers</li><li>Send messages that you or an Owner approve</li></ul><button class="btn btn-sm ${A.ob.mail.gmail ? '' : 'btn-primary'}" data-act="obMail">${A.ob.mail.gmail ? 'Selected ✓ (simulated)' : 'Connect Gmail'}</button></div></div><div class="card mb16"><div class="card-b row"><div class="sp"><b>Outlook (Microsoft 365)</b><div class="small muted">Planned after the first release</div></div><span class="badge b-neutral nodot">Coming soon</span></div></div>${nav()}`;
  if (n === 4) b = `<h2 class="mb16">Import your records</h2><div class="grid g2"><div class="card"><div class="card-b"><b>Upload CSV or PDF</b><p class="small muted">Invoices and payments from your accounting system or bank.</p><a class="btn btn-sm" href="app.html#/invoices/import" data-act="owner">Open import wizard</a></div></div><div class="card"><div class="card-b"><b>Explore with demo data</b><p class="small muted">Clearly labelled sample records you can remove in one action.</p><button class="btn btn-sm btn-primary" data-act="toast" data-msg="Demo data selected — it will be labelled and removable">${A.demo ? 'Selected' : 'Use demo data'}</button></div></div></div>${nav()}`;
  if (n === 5) b = `<h2 class="mb16">Invite your team</h2><p class="muted mb16">Invited people join this organization as AR Specialists.</p>${form('ft', fld('Email', '<input class="in" data-email name="e" placeholder="name@company.com">', '', 'Enter a valid email address'))}<button class="btn btn-sm" data-act="obInvite">Add invitation</button><ul class="small mt16">${A.ob.team.map(e => `<li>${esc(e)} — AR Specialist <span class="badge b-blue nodot">Invitation queued</span></li>`).join('') || '<li class="muted">No invitations yet.</li>'}</ul>${nav()}`;
  if (n === 6) b = `<h2 class="mb16">Preferences</h2>${fld('Timezone', '<select class="in"><option>America/New_York</option><option>Europe/London</option><option>Europe/Berlin</option></select>', 'Decides when an invoice becomes overdue.')}${fld('Default payment terms (days)', '<input class="in" type="number" value="30">')}<label class="check mb16"><input type="checkbox" checked> <span><b>Auto-apply exact matches</b><br><span class="muted">Only when invoice number and amount match exactly. Visible with undo in Reconciliation.</span></span></label><div class="banner">${ic('lock')}<div>Approval defaults: write-offs, refund decisions and final notices always need an Owner. Change this later in Settings.</div></div>${nav('Enter dashboard', false)}`;
  return `<div class="proto"><b>PROTOTYPE</b><span class="hide-s">Onboarding is resumable; progress is stored per organization</span><span class="sp"></span><a href="app.html">Skip to app</a></div><main class="auth"><div class="box wide"><a class="logo" href="index.html">${LOGO_D}Venn</a>${steps}${b}</div></main>`;
}
function renderAuth() {
  const h = (location.hash.slice(1) || '/login').split('?')[0], p = h.split('/').filter(Boolean);
  document.getElementById('root').innerHTML = p[0] === 'onboarding' ? onboarding(+p[1] || 1) : (AUTH[p[0]] || AUTH.login)();
  document.title = 'Venn — ' + (p[0] || 'sign in');
}
render = renderAuth;
const enter = role => { store.set('venn_role', role); location.href = 'app.html#/dashboard'; };
Object.assign(ACT, {
  quick: el => enter(el.dataset.role),
  doLogin: () => { if (validate($('#fl'))) enter('owner'); },
  doSignup: () => { const f = $('#fs'); const ok = validate(f); const c = $('input[type=checkbox]', f); if (!ok || !c.checked) { if (!c.checked) toast('Please accept the terms to continue'); return; } A.email = $('[name=e]', f).value; go('#/verify'); },
  verified: () => go('#/onboarding/1'),
  resend: () => { const b = $('#rs'); b.disabled = true; let s = 30; const t = setInterval(() => { $('#rsn') && ($('#rsn').textContent = `Resend available in ${--s}s`); if (s <= 0) clearInterval(t); }, 1000); toast('Verification email sent again'); },
  doForgot: () => { if (!validate($('#ff'))) return; $('#ff').innerHTML = `<div class="banner ok">${ic('check')}<div>If an account exists for that address, a reset link is on its way. This message is the same either way.</div></div>`; },
  doReset: () => { const f = $('#fr'); if (!validate(f)) return; if ($('[name=p]', f).value !== $('[name=c]', f).value) { toast('Passwords do not match'); return; } toast('Password updated'); go('#/login'); },
  acceptInvite: () => { if (validate($('#fv'))) enter('ar'); },
  obToggle: el => { A.ob.sources[el.dataset.k] = !A.ob.sources[el.dataset.k]; render(); },
  obMail: () => { A.ob.mail.gmail = !A.ob.mail.gmail; render(); },
  obInvite: () => { const f = $('#ft'); if (!validate(f)) return; const e = $('[name=e]', f).value.trim(); if (e) { A.ob.team.push(e); render(); } else toast('Enter an email first'); },
  skip: el => go(el.getAttribute('href')),
  owner: el => { store.set('venn_role', 'owner'); location.href = el.getAttribute('href'); },
  obNext: el => { const n = +el.dataset.n; if (n === 1 && !validate($('#fo'))) return; if (n === 6) return enter('owner'); go('#/onboarding/' + (n + 1)); },
});
